{"explanation":"At a fraction \(z/H\) of the way from the tip, a cone’s cross-sectional radius is \((z/H)R\), so its area is \(\pi R^2(z/H)^2\). Adding these cross-sectional areas from tip to base gives \(\frac13\pi R^2H\), while the cylinder has constant area \(\pi R^2\) throughout, so its volume is \(\pi R^2H\).","manimCode":"const title = new Text({ text: 'Same base radius R and height H', color: WHITE, fontSize: 30 });
title.moveTo([0, 3.35, 0]);

const cone = new Polygon({
  vertices: [[-3, 1.85, 0], [-4.7, -1.85, 0], [-1.3, -1.85, 0]],
  color: BLUE
});
cone.setFill(BLUE_E, 0.35).setStrokeWidth(3);

const cyl = new Rectangle({ width: 3.4, height: 3.7, color: ORANGE });
cyl.moveTo([3, 0, 0]);
cyl.setFill(ORANGE, 0.22).setStrokeWidth(3);

const coneLabel = new Text({ text: 'cone', color: BLUE_A, fontSize: 26 });
coneLabel.moveTo([-3, 2.35, 0]);
const cylLabel = new Text({ text: 'cylinder', color: ORANGE, fontSize: 26 });
cylLabel.moveTo([3, 2.35, 0]);

const baseCone = new Polygon({ vertices: [[-4.7, -1.85, 0], [-1.3, -1.85, 0]], color: YELLOW });
baseCone.setStrokeWidth(5);
const baseCyl = new Polygon({ vertices: [[1.3, -1.85, 0], [4.7, -1.85, 0]], color: YELLOW });
baseCyl.setStrokeWidth(5);

const u = new ValueTracker(0.58);
const coneSlice = new Polygon({ vertices: [[-3.1, 0, 0], [-2.9, 0, 0]], color: YELLOW });
coneSlice.setFill(YELLOW, 0.7).setStrokeWidth(2);
const cylSlice = new Polygon({ vertices: [[1.3, 0, 0], [4.7, 0, 0]], color: YELLOW });
cylSlice.setFill(YELLOW, 0.7).setStrokeWidth(2);

function updateSlices() {
  const q = u.getValue();
  const y = 1.85 - 3.7 * q;
  const halfWidth = 1.7 * q;
  const band = 0.09;
  coneSlice.setVertices([
    [-3 - halfWidth, y - band, 0], [-3 + halfWidth, y - band, 0],
    [-3 + halfWidth, y + band, 0], [-3 - halfWidth, y + band, 0]
  ]);
  cylSlice.setVertices([[1.3, y - band, 0], [4.7, y - band, 0], [4.7, y + band, 0], [1.3, y + band, 0]]);
}
coneSlice.addUpdater(updateSlices);
cylSlice.addUpdater(updateSlices);

const relation = new MathTex({ latex: 'r(z)=\\frac{z}{H}R' });
await relation.waitForRender();
relation.moveTo([-3, -2.55, 0]);
relation.setColor(YELLOW);

const derivation = new MathTex({ latex: 'V_{\\rm cone}=\\int_0^H \\pi\\left(\\frac{zR}{H}\\right)^2 dz=\\frac13\\pi R^2H' });
await derivation.waitForRender();
derivation.moveTo([0, -3.15, 0]);
derivation.setColor(BLUE_A);

const comparison = new MathTex({ latex: 'V_{\\rm cylinder}=\\pi R^2H\\quad\\Rightarrow\\quad V_{\\rm cone}=\\frac13V_{\\rm cylinder}' });
await comparison.waitForRender();
comparison.moveTo([0, -3.65, 0]);
comparison.setColor(ORANGE);

scene.add(title, cone, cyl, baseCone, baseCyl, coneLabel, cylLabel, coneSlice, cylSlice, relation, derivation, comparison);

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'Slice position z/H', min: 0.05, max: 1, value: 0.58, step: 0.01,
  onChange: (val) => u.setValue(val)
});

await scene.wait(999999);"}

